def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add empty field if we're starting a new field
            if i == 0 or line[i-1] == ',':
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(field)
                        # Skip the comma if present
                        if i < len(line) and line[i] == ',':
                            i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

